import { ProblemException } from '@cadenway/nest-common';
import type { z } from 'zod';

/**
 * Interface GeneratedResponse
 *
 * @description
 * What a function generated by orval resolves with: the status and the parsed body of a response
 * the internal HTTP client let through (below 400).
 */
export interface GeneratedResponse {
  // #region Properties
  /**
   * Property status
   *
   * @description
   * HTTP status of the response.
   *
   * @type {number}
   * @readonly
   */
  readonly status: number;

  /**
   * Property data
   *
   * @description
   * Parsed JSON body, not validated yet.
   *
   * @type {unknown}
   * @readonly
   */
  readonly data: unknown;
  // #endregion
}

/**
 * Function outsideContract
 *
 * @description
 * Builds the problem of a response of an internal service that does not match its contract: a
 * defect of that service, answered as `503 upstream.failed`, as the internal HTTP client answers a
 * server error. The cause names the offending members, never their values, which may be secrets.
 *
 * @param {string} service - Name of the called service, as `details.service`.
 * @param {string} operation - `operationId` of the call.
 * @param {string} reason - What did not match.
 * @returns {ProblemException} The problem to throw.
 */
export function outsideContract(
  service: string,
  operation: string,
  reason: string,
): ProblemException {
  return new ProblemException({
    status: 503,
    code: 'upstream.failed',
    detail: 'A service this request depends on is not available.',
    details: { service },
    cause: new Error(`${service} answered ${operation} outside its contract: ${reason}.`),
  });
}

/**
 * Function expectStatus
 *
 * @description
 * Checks that a response has the success status of its operation.
 *
 * @param {string} service - Name of the called service.
 * @param {string} operation - `operationId` of the call.
 * @param {GeneratedResponse} response - Response of the generated function.
 * @param {number} status - Success status of the operation.
 * @throws {ProblemException} 503 `upstream.failed` for another status.
 */
export function expectStatus(
  service: string,
  operation: string,
  response: GeneratedResponse,
  status: number,
): void {
  if (response.status !== status) {
    throw outsideContract(service, operation, `status ${String(response.status)}`);
  }
}

/**
 * Function expectBody
 *
 * @description
 * Checks a response against its operation: the success status, then the body against the zod
 * validator of `@cadenway/contracts`. The parsed value keeps the members of the contract only, so
 * an unexpected member of the called service never travels further.
 *
 * @param {string} service - Name of the called service.
 * @param {string} operation - `operationId` of the call.
 * @param {GeneratedResponse} response - Response of the generated function.
 * @param {number} status - Success status of the operation.
 * @param {TSchema} schema - Validator of the success body.
 * @returns {z.output<TSchema>} The validated body.
 * @throws {ProblemException} 503 `upstream.failed` when the status or the body does not match.
 */
export function expectBody<TSchema extends z.ZodType>(
  service: string,
  operation: string,
  response: GeneratedResponse,
  status: number,
  schema: TSchema,
): z.output<TSchema> {
  expectStatus(service, operation, response, status);
  return conformBody(service, operation, schema, response.data);
}

/**
 * Function conformBody
 *
 * @description
 * Checks a body against a zod validator of `@cadenway/contracts`: the answer of an internal
 * service against its internal contract, or that answer against the public contract of the route
 * that relays it. The parsed value keeps the members of the contract only, so a member the
 * called service adds later never reaches the applications before the public contract declares
 * it.
 *
 * @param {string} service - Name of the called service.
 * @param {string} operation - `operationId` of the call or of the public route.
 * @param {TSchema} schema - Validator of the body.
 * @param {unknown} body - The body.
 * @returns {z.output<TSchema>} The validated body.
 * @throws {ProblemException} 503 `upstream.failed` when the body does not match.
 */
export function conformBody<TSchema extends z.ZodType>(
  service: string,
  operation: string,
  schema: TSchema,
  body: unknown,
): z.output<TSchema> {
  const parsed: z.ZodSafeParseResult<z.output<TSchema>> = schema.safeParse(body);
  if (!parsed.success) {
    const members: string = parsed.error.issues
      .map((issue: z.core.$ZodIssue) => issue.path.join('.') || '(body)')
      .join(', ');
    throw outsideContract(service, operation, `invalid ${members}`);
  }
  return parsed.data;
}

/**
 * Function answered
 *
 * @description
 * Awaits a generated call. The generated code parses a success body with `JSON.parse`, whose
 * `SyntaxError` quotes part of the body, which may hold a token: a body that is not JSON becomes
 * `503 upstream.failed` without that message, so it reaches neither the browser nor the log line
 * of the request. Every other error, the problems of the internal HTTP client included, is thrown
 * unchanged.
 *
 * @param {string} service - Name of the called service.
 * @param {string} operation - `operationId` of the call.
 * @param {Promise<TResponse>} call - The generated call.
 * @returns {Promise<TResponse>} What the call resolved with.
 * @throws {ProblemException} 503 `upstream.failed` for a body that is not JSON.
 */
export async function answered<TResponse>(
  service: string,
  operation: string,
  call: Promise<TResponse>,
): Promise<TResponse> {
  try {
    return await call;
  } catch (error) {
    if (error instanceof SyntaxError) {
      throw outsideContract(service, operation, 'a body that is not JSON');
    }
    throw error;
  }
}
